(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, dS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv = Math.sin(d*f-t*sp);
    aS += wv*w; iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    dS += Math.sin(d*f*1.3-t*sp*0.4+2.8)*w*0.5;
  }
  const act=aS/6.65, inh=iS/6.65, dif=dS/6.65;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.065+t*1.8)*Math.cos(sy*0.055-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08+ang*2-t*2.2)*0.15;
  const hex = Math.sin(sx*0.087+sy*0.15)*Math.sin(sx*0.15-sy*0.087+t*0.3)*0.3;
  const micro = Math.sin(sx*0.22+t*3)*Math.sin(sy*0.22-t*2.5)*Math.sin((sx+sy)*0.16+t*2)*0.15;
  const feedback = Math.sin(act*2.5+inh*1.8)*0.2;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral+hex+micro+dif*0.3+feedback)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.08-t*0.7)*0.3)*1.5)*0.25;
  const edge = 1.0-Math.pow(Math.abs(reaction),0.8)*0.15;
  const blend = reaction*0.65+cell*0.2+Math.sin(dist*0.03-t*0.5)*0.15, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,95],[18,85,120],[25,135,130],[45,170,125],
    [180,190,60],[220,155,55],[210,100,65],[175,55,60],[120,30,55],
    [65,18,48],[25,12,42],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const glow = Math.max(0, reaction*0.3)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*20)|0)
  ];
}
